struct hw_cq * efct_hw_new_cq ( struct hw_eq * eq , u32 entry_count ) { struct efct_hw * hw = eq -> hw ; struct hw_cq * cq = kzalloc ( sizeof ( * cq ) , GFP_KERNEL ) ; if ( ! cq ) { return NULL ; } cq -> eq = eq ; cq -> type = SLI4_QTYPE_CQ ; cq -> instance = eq -> hw -> cq_count ++ ; cq -> entry_count = entry_count ; cq -> queue = & hw -> cq [ cq -> instance ] ; INIT_LIST_HEAD ( & cq -> q_list ) ; if ( sli_queue_alloc ( & hw -> sli , SLI4_QTYPE_CQ , cq -> queue , cq -> entry_count , eq -> queue ) ) { efc_log_err ( hw -> os , "CQ[%d] allocation failure len=%d\n" , eq -> instance , eq -> entry_count ) ; return NULL ; } hw -> hw_cq [ cq -> instance ] = cq ; INIT_LIST_HEAD ( & cq -> list_entry ) ; list_add_tail ( & cq -> list_entry , & eq -> cq_list ) ; efc_log_debug ( hw -> os , "create cq[%2d] id %3d len %4d\n" , cq -> instance , cq -> queue -> id , cq -> entry_count ) ; return cq ; } 